/* @lc app=leetcode id=3920 lang=kotlin */ class Solution { fun maxFixedPoints(nums: IntArray): Int = nums.indices.filter { nums[it] <= it }.map { (it - nums[it]) to nums[it] }.sortedWith(compareBy({ it.first }, { it.second })).fold(ArrayList<Int>()) { t, p -> t.also { t.binarySearch(p.second).let { r -> (if (r >= 0) r else -r - 1).let { i -> if (i == t.size) t.add(p.second) else t.set(i, p.second) } } } }.size }